  "여러 AI CLI(Claude Code·Codex·Gemini CLI·Hermes)와 OpenAI 호환 API를 한 화면에서 팀으로 묶어 쓰는 로컬 앱이야. 서버는 이 PC(127.0.0.1)에서만 열리고, 런타임 의존성이 없어 가벼워.": "複数の AI CLI（Claude Code・Codex・Gemini CLI・Hermes）と OpenAI 互換 API を、1つの画面でチームとしてまとめて使うローカルアプリです。サーバーはこの PC（127.0.0.1）でのみ開き、ランタイム依存がないので軽量です。",
