  "Claude Code·Codex CLI에서 하던 대화를 골라 여기서 이어서 할 수 있어. 불러올 때 원래 기록은 읽기만 해. Claude는 갈래(포크)로 이어가서 원래 기록이 그대로 남고, Codex는 같은 대화에 이어 붙어(Codex에서도 계속 볼 수 있어).": "Claude Code や Codex CLI で進めていた会話を選んで、ここで続けられます。読み込み時は元の記録を読むだけです。Claude は分岐（フォーク）で続けるので元の記録はそのまま残り、Codex は同じ会話の続きに追加されます（Codex 側でも引き続き見られます）。",
