  "Claude Code · Codex 공식 API 키": "Claude Code・Codex の公式 API キー",
  "AI 계정 탭에서 결제 방식을 API 키로 고른 AI만 이 키를 써. 비우면 PC 환경변수의 키를 써.": "AI アカウントタブで課金方式を API キーにした AI だけがこのキーを使います。空欄なら PC の環境変数のキーを使います。",
