  "ACP 에이전트 (Agent Client Protocol)": "ACP エージェント（Agent Client Protocol）",
  "ACP 표준을 지원하는 코딩 에이전트를 그대로 붙여. 에이전트 편집에서 AI를 ACP 에이전트로 고르고, 모델 칸에서 여기 추가한 에이전트를 골라. 로그인·요금은 각 에이전트 규정을 따라.": "ACP 標準に対応したコーディングエージェントをそのまま接続します。エージェント編集で AI を ACP エージェントにし、モデル欄でここに追加したエージェントを選んでください。ログイン・料金は各エージェントの規約に従います。",
  "인자(띄어쓰기로 구분)": "引数（スペース区切り）",
  "설치됨": "インストール済み",
  "새 ACP 에이전트": "新しい ACP エージェント",
  "직접 추가": "手動で追加",
  "ACP 에이전트": "ACP エージェント",
  "Agent Client Protocol 표준 · Gemini CLI·Hermes·OpenCode·Goose 등": "Agent Client Protocol 標準・Gemini CLI・Hermes・OpenCode・Goose など",
  "설정 → API 키·로컬 모델 → ACP 에이전트에서 추가해줘": "設定 → API キー・ローカルモデル → ACP エージェントで追加してください",
  "추가한 ACP 에이전트 명령을 찾을 수 없어. 설치했는지 확인해줘.": "追加した ACP エージェントのコマンドが見つかりません。インストールされているか確認してください。",
  "쓸 ACP 에이전트가 없어. 설정 → API 키·로컬 모델 → ACP 에이전트에서 추가해줘.": "使える ACP エージェントがありません。設定 → API キー・ローカルモデル → ACP エージェントで追加してください。",
