  // ── 계정 사용 원칙 (settings.js·main.js) ──
  "계정 사용 원칙 보기": "アカウント利用の原則を見る",
  "계정 사용 원칙": "アカウント利用の原則",
  "오피스 크루는 내 PC에 설치·로그인한 공식 CLI를 그대로 실행해. 로그인 토큰은 읽지도, 저장하지도, 다른 곳으로 보내지도 않아.": "Office Crew は、PC にインストールしてサインイン済みの公式 CLI をそのまま実行します。サインイントークンを読み取ったり、保存したり、外部に送ったりすることはありません。",
  "구독 로그인은 내 PC에서 나 혼자 쓰는 용도야. 계정을 나눠 쓰거나 다른 사람에게 서비스로 제공하지 마.": "サブスクリプションのサインインは、ご自身の PC でご自身が使うためのものです。アカウントを共有したり、他の人へサービスとして提供したりしないでください。",
  "제품을 만들거나 회사에서 쓰거나 사람 없이 돌릴 땐 Claude·Codex 결제 방식을 API 키로 바꿔줘 (설정 → AI 계정).": "製品を作る、会社で使う、無人で動かす場合は、Claude・Codex の課金方式を API キーに切り替えてください（設定 → AI アカウント）。",
  "Hermes에서 Anthropic을 고르면 Claude Code 로그인을 가져다 쓸 수 있어. 대신 Anthropic API 키나 다른 제공자를 지정해줘.": "Hermes で Anthropic を選ぶと、Claude Code のサインインを流用することがあります。代わりに Anthropic API キーか別のプロバイダーを指定してください。",
  "약관은 바뀔 수 있고 이 안내는 법률 자문이 아니야. 각 서비스의 최신 약관을 확인해줘.": "規約は変わることがあり、この案内は法的助言ではありません。各サービスの最新の規約をご確認ください。",
