  "OpenRouter (Hermes·Grok·DeepSeek 등)": "OpenRouter（Hermes・Grok・DeepSeek など）",
  "리서처": "リサーチャー",
  "너는 조사 담당이야. 필요한 자료를 찾아 핵심 사실과 출처를 정리해. 확인 안 된 건 \"추정\"이라고 표시해.": "あなたは調査担当です。必要な資料を探し、要点となる事実と出典をまとめてください。未確認の内容は「推定」と明記してください。",
  "정리왕": "整理役",
  "너는 정리 담당이야. 앞 단계 결과를 중복 없이 구조화해서 표·목록으로 정리해.": "あなたは整理担当です。前の段階の結果を重複なく構造化し、表や箇条書きにまとめてください。",
  "분석가": "アナリスト",
  "너는 분석 담당이야. 정리된 내용을 근거로 판단·우선순위·위험을 분석하고 실행 계획을 세워.": "あなたは分析担当です。整理された内容を根拠に、判断・優先順位・リスクを分析し、実行計画を立ててください。",
  "빌더": "ビルダー",
  "너는 빌드 담당이야. 분석·계획을 바탕으로 작업 폴더에 실제 결과물을 만들고, 만든 파일과 확인 결과를 보고해.": "あなたはビルド担当です。分析と計画をもとに作業フォルダーに実際の成果物を作り、作ったファイルと確認結果を報告してください。",
  "기본 팀": "基本チーム",
  "조사(소네트) → 정리(솔) → 분석(오푸스 하이) → 빌드(오푸스 X하이)": "調査（Sonnet）→ 整理（Sol）→ 分析（Opus 高）→ ビルド（Opus 超高）",
  "자동 라우팅 팀": "自動ルーティングチーム",
  "로그인된 AI 중에서 역할별 모델·노력을 자동 배정 (조사→정리→분석→빌드→교차 검수)": "サインイン済みの AI から役割ごとにモデルと推論の深さを自動で割り当て（調査→整理→分析→ビルド→クロスレビュー）",
  "자동 조사": "自動調査",
  "필요한 자료를 찾아 핵심 사실과 출처를 정리해. 확인 안 된 건 \"추정\"이라고 표시해.": "必要な資料を探し、要点となる事実と出典をまとめてください。未確認の内容は「推定」と明記してください。",
  "자동 정리": "自動整理",
  "앞 단계 결과를 중복 없이 표·목록으로 정리해.": "前の段階の結果を重複なく表や箇条書きにまとめてください。",
  "자동 분석": "自動分析",
  "근거를 바탕으로 판단·우선순위·위험을 분석하고 실행 계획을 세워.": "根拠をもとに判断・優先順位・リスクを分析し、実行計画を立ててください。",
  "자동 빌드": "自動ビルド",
  "계획대로 작업 폴더에 실제 결과물을 만들고, 만든 파일과 확인 결과를 보고해.": "計画どおり作業フォルダーに実際の成果物を作り、作ったファイルと確認結果を報告してください。",
  "자동 검수": "自動レビュー",
  "만든 결과를 요구사항 기준으로 검토해 문제·누락·개선점을 목록으로 지적해.": "成果物を要件に照らしてレビューし、問題・抜け・改善点を一覧で指摘してください。",
  // ── 검증 수정 (routing·acp·orchestrator) ──
  "사용률이 기준을 넘어 {time}까지 피하는 중": "使用率が基準を超えたため {time} まで回避中",
  "ACP 에이전트 \"{id}\"를 찾을 수 없어. 에이전트 편집의 모델 칸에서 다시 골라줘.": "ACP エージェント「{id}」が見つかりません。エージェント編集のモデル欄で選び直してください。",
  "{from} 오류가 한도 문구처럼 보이지만, 내 PC 모델 작업은 다른 AI로 넘기지 않아.": "{from} のエラーは使用量の上限のようですが、ローカルモデルに割り当てた作業は別の AI に引き継ぎません。",
  // ── 재검증 수정 (index) ──
  "가려진 값({name})을 고치려면 지우고 새로 입력해줘.": "隠された値（{name}）を変えるには、消してから新しく入力してください。",
  // ── 최종 검증 수정 (index) ──
  "가려진 값은 비밀값 이름으로만 옮길 수 있어. {name}에는 새로 입력해줘.": "隠された値は秘密情報の名前にしか移せません。{name} には新しく入力してください。",
