  "지우기": "削除",
  "투명 배경 PNG를 추천해. 긴 변 256px로 줄여 이 PC에만 저장돼. 작은 도트 그림은 선명하게 확대돼.": "透明背景の PNG がおすすめ。長辺を 256px に縮めて、この PC にだけ保存されるよ。小さなドット絵はくっきり拡大されるよ。",
  "내 마을": "マイ村",
  "마을 꾸미기 (집 그림 바꾸기)": "村をカスタマイズ（家を変える）",
  "크루 마을: 쉬는 에이전트는 자기 집에 들어가 있고, 일을 시작하면 회사로 출근해. 집 그림을 내 그림으로 바꿀 수 있어.": "クルー村：待機中のエージェントは自分の家にいて、仕事が始まると会社に出勤するよ。家は自分の画像に変えられるよ。",
