  "쉬는 에이전트가 들어가 있는 집이야. 투명 배경 PNG를 추천해(예: 캡슐·둥지·텐트). 그림은 이 PC에만 저장돼.": "待機中のエージェントが入っている家だよ。透明背景の PNG がおすすめ（例：カプセル・巣・テント）。画像はこの PC にだけ保存されるよ。",
