  "정해 둔 요일·시각이 되면 팀이 알아서 출근해서 일해. 결과는 새 세션으로 남고, 승인 단계가 있으면 기다리는 일에 올라와.": "決めた曜日・時刻になると、チームが自分で出勤して働くよ。結果は新しいセッションに残り、承認ステップがあれば「待っていること」に表示されるよ。",
