  "추가할 ChatGPT 계정 이름(예: 회사 계정)": "追加する ChatGPT アカウントの名前 (例: 仕事用)",
  "계정 {n}": "アカウント {n}",
  "계정 이름": "アカウント名",
  "ChatGPT 계정이 여러 개면 \"계정 추가\"로 붙여. 한 계정이 한도에 걸리면 자동 이어받기가 다음 계정으로 넘겨.": "ChatGPT アカウントが複数あるなら「アカウント追加」でつないで。1つが上限に達すると、自動引き継ぎが次のアカウントに回すよ。",
  "계정 추가": "アカウント追加",
  "계정 빼기": "アカウントを外す",
  "'{name}' 계정을 만들었어. 그 줄의 로그인을 눌러 다른 ChatGPT 계정으로 로그인해.": "アカウント「{name}」を作ったよ。その行のログインを押して、別の ChatGPT アカウントでログインして。",
  "'{name}' 계정을 목록에서 뺄까? 이 계정을 쓰던 에이전트는 다른 AI로 바꿔야 해. 로그인 정보 폴더는 지우지 않아.": "アカウント「{name}」を一覧から外す？このアカウントを使っていたエージェントは別の AI に変える必要があるよ。ログイン情報のフォルダは消さないよ。",
  "출처": "出どころ",
  "한글 설명이 없는 스킬 {n}개 중 최대 {batch}개를 고른 에이전트가 번역해. 그 AI의 사용량을 써. 시작할까?": "選んだエージェントが、韓国語の説明がないスキル {n} 個のうち最大 {batch} 個を翻訳するよ。その AI の使用量を使う。始める？",
  "번역을 시작했어. 끝나면 목록에 한글 설명이 붙어.": "翻訳を始めたよ。終わると一覧に韓国語の説明が付くよ。",
  "한글 설명이 없는 스킬 {n}개": "韓国語の説明がないスキル {n} 個",
  "새로 깐 스킬은 영어 설명 그대로야. 고른 에이전트가 번역하고, 결과는 이 PC에만 저장돼.": "新しく入れたスキルは英語の説明のままだよ。選んだエージェントが翻訳して、結果はこの PC だけに保存されるよ。",
