  "이 AI의 CLI에 깔린 스킬은 보통 필요할 때 CLI가 알아서 꺼내 써. 여기서 고르면 매번 지침에 붙여서 항상 적용돼(토큰을 더 써).": "この AI の CLI に入っているスキルは、ふつう必要なときに CLI が自分で使うよ。ここで選ぶと毎回指示に付けて常に適用される (トークンを多く使う)。",
