  "kind 에는 막힌 까닭 하나를 적어: unclear(지시가 모호함) · input(넘겨받은 것이 틀림) · capability(권한·도구가 없음) · dependency(다른 일이 먼저 끝나야 함). 모르면 빼.": "kind には止まった理由を一つ書いて: unclear（指示が曖昧）· input（受け取った内容が誤り）· capability（権限・ツールがない）· dependency（別の作業が先に終わる必要がある）。分からなければ省いて。",
  "밖으로 나가는 일(원격 저장소에 올리기·배포·메일·메시지 보내기·게시·결제)과 작업 폴더 밖의 파일 지우기는 하기 전에 질문 블록으로 물어. 작업 폴더 안에서 고치고 만드는 건 묻지 말고 해.": "外に出ること（リモートリポジトリへのプッシュ・デプロイ・メールやメッセージの送信・投稿・支払い）と作業フォルダの外のファイル削除は、する前に質問ブロックで聞いて。作業フォルダ内での修正・作成は聞かずにやって。",
  "밖으로 나가는 일(원격 저장소에 올리기·배포·메일·메시지 보내기·게시·결제)과 작업 폴더 밖의 파일 지우기는 하지 마. 필요하면 답에 적어 둬. 작업 폴더 안에서 고치고 만드는 건 그냥 해.": "外に出ること（リモートリポジトリへのプッシュ・デプロイ・メールやメッセージの送信・投稿・支払い）と作業フォルダの外のファイル削除はしないで。必要なら回答に書いておいて。作業フォルダ内での修正・作成はそのままやって。",
