  "\"{label}\" 단계의 {id}({name})이(가) 오류로 끝났어.": "「{label}」段階の{id}（{name}）がエラーで終わりました。",
  "{id}: 기다린 앞 카드 {ids}이(가) 결과 없이 끝났고, 이 카드도 끝나지 못했어({status}).": "{id}: 待っていた前のカード{ids}が結果なしで終わり、このカードも終われませんでした（{status}）。",
  "조사 담당 {name}의 AI({ai}) 사용량 한도가 거의 다 차서 \"{label}\" 단계에서는 회의 중 조사를 껐어.": "調査担当{name}のAI（{ai}）の使用量が上限間近なので、「{label}」段階では会議中の調査をオフにしました。",
  "확인 못 함: 조사 담당 AI의 사용량 한도가 거의 다 차서 회의 중 조사를 껐어.": "確認できず: 調査担当のAIの使用量が上限間近なので、会議中の調査をオフにしました。",
