  "{name}: 요청한 AI는 {asked}인데 {ran}(으)로 돌았어(이유: {why}).": "{name}: 要求したAIは{asked}でしたが、{ran}で動きました（理由: {why}）。",
  "{name}의 AI({ai}) 사용량 한도가 거의 다 차서 인수인계 메모 먼저 쓰기를 건너뛰었어. 한도가 줄면 부가 일부터 멈춰.": "{name}のAI（{ai}）の使用量が上限間近なので、引き継ぎメモを先に書くのを飛ばしました。上限が近いときは付随作業から止めます。",
